Q: Creating a textarea with auto-resize A: <p>I use this solution, works fine:</p>
<pre><code>&lt;textarea placeholder=&quot;Start typing rows...&quot;&gt;&lt;/textarea&gt;
</code></pre>
<pre><code>textarea { padding:1em }
</code></pre>
<pre><code>const textarea = document.querySelector('textarea');
textarea.addEventListener('input', function () {
    textarea.style.height = '';
    textarea.style.height = Math.min(textarea.scrollHeight, 300) + 'px';
});
</code></pre>
